66-8427-b7f62c91ae8a","evidence-15da1e6d-9c13-49f1-a146-f94eb1d8e564","evidence-27ebc57b-491d-46f1-bdb3-33df17720f9f","evidence-89fe01db-82bb-475e-9d76-5a379bda0e07","evidence-e925f9c6-bafa-4a0e-bc35-de2a031a6cc9"],"id":"blk-feat-reset","kind":"feature","requirementIds":["blk-prod-scope","blk-prod-outcomes"],"stage":"product","title":"功能特性：一键即时清空、节点物理替换与代际解耦契约"},{"content":"1. 用户点击底部橙色圆形清空按钮（resetButton）。
2. 执行 ResetController.handleReset() 核心复位流程：
   a. 第一优先级调用 DebounceScheduler.cancel()：清除当前排队的 pendingTimerId，递增 schedulerEpoch 使任何已进入宏任务队列的旧定时器回调彻底失效；
   b. 递增全局代际计数：inputGeneration++；
   c. 记录旧节点引用 const oldNode = activeInputNode;；
   d. 实例化全新输入元素：const newNode = document.createElement('input');；
   e. 复制原有全部 DOM 属性与无障碍配置：newNode.type = 'text'; newNode.id = oldNode.id; newNode.name = oldNode.name; newNode.className = oldNode.className; newNode.placeholder = oldNode.placeholder; newNode.setAttribute('aria-label', oldNode.getAttribute('aria-label') || '项目名输入'); newNode.value = '';；
   f. 调用 InputController.bindInputNode(newNode, inputGeneration) 为新节点完成专属闭包事件监听绑定（传入当前代际作为 bornGeneration）；
   g. 执行 DOM 物理节点替换：oldNode.replaceWith(newNode);；
   h. 更新全局引用：activeInputNode = newNode;；
   i. 将顶部展示区复位为灰字占位符：DisplayRenderer.renderPlaceholder(displayElement, '【等待输入核对】');；
   j. 移除可见的校验错误 DOM 节点并清除边框高亮样式：FeedbackBanner.clearInputError(activeInputNode, errorContainer);；
   k. 调用 activeInputNode.focus(); 确保键盘输入焦点停留在新输入框内。
3. 旧节点迟到事件隔离拦截：
   - 若在重置完成后，输入法或浏览器向 oldNode 派发迟到的 compositionend、beforeinput 或 input 事件；
   - 事件触发 oldNode 对应的旧闭包函数，守卫执行 if (e.currentTarget !== node || node !== activeInputNode || bornGeneration !== inputGeneration || !document.body.contains(node)) return;；
   - 由于 node !== activeInputNode（oldNode !== newNode）且 bornGeneration !== inputGeneration，守卫立即直接 return；
   - 旧事件完全不执行任何逻辑，不修改 activeInputNode.value，不调度防抖，不修改新节点组合状态。
4. 新输入顺畅恢复：
   - 用户在 activeInputNode 中键入字符、粘贴或启动新输入法合成，新节点的闭包正常匹配 bornGeneration === inputGeneration，正常流转 300ms 防抖倒计时与结果展示。
5. 流程结束，界面完全处于干净就绪态。","dependsOn":["blk-feat-reset"],"evidenceIds":["evidence-1e3fc8ef-8a1e-404f-a931-72f46fd0d8ed","evidence-6f045d0d-928d-4f66-8427-b7f62c91ae8a","evidence-15da1e6d-9c13-49f1-a146-f94eb1d8e564","evidence-27ebc57b-491d-46f1-bdb3-33df17720f9f","evidence-89fe01db-82bb-475e-9d76-5a379bda0e07","evidence-e925f9c6-bafa-4a0e-bc35-de2a031a6cc9"],"id":"blk-flow-reset","kind":"flow","requirementIds":["blk-feat-reset"],"stage":"product","title":"交互流程：清空重置、DOM节点替换与代际闭包解耦流转"},{"content":"本地单页面原型核对视图（Single Page View），基于 fixture.png 原生像素结构并在删除确认按钮后映射布局，并规范节点物理替换时的页面保真：
1. 视觉底色：纯白底色（#FFFFFF）清爽背景，无多余装饰纹理；
2. 顶部展示区域：映射 fixture.png 上方“Q7M4-8261”视觉层级与相对空间位置，作为核对结果大字展示区（初始显示灰色占位文字，300ms 防抖完成后以高对比黑色大字显示，支持 word-break: break-all 换行防撑破）；
3. 底部操作区域：依据已批准决策彻底移除原 fixture.png 左下蓝色矩形色块（确认按钮已删除），仅保留映射右下方橙色圆形色块的橙色实心圆形【清空】操作按钮（底色 #FF5500）；
4. 输入表单区域：在桌面端位于展示区与底部清空按钮区之间居中排布，提供单行文本输入框；在清空触发输入框节点替换（replaceWith）时，严格保持容器几何尺寸、边框、内边距、字体样式、id、name、label 关联及 WAI-ARIA 属性（aria-label）完全不变，避免界面发生跳动或焦点迷失；
5. 状态覆盖：涵盖就绪初始态（占位灰字）、防抖等待态（草稿输入中/IME选词中）、清空节点替换就绪态（新输入框已就绪回焦，旧节点解耦移出）、正常核对态（大字黑色显示）、错误提示态（红字就地显示）、异常防护态（顶部横幅警示）与纯离线本地加载态。","dependsOn":["blk-prod-scope"],"evidenceIds":["evidence-1e3fc8ef-8a1e-404f-a931-72f46fd0d8ed","evidence-6f045d0d-928d-4f66-8427-b7f62c91ae8a","evidence-15da1e6d-9c13-49f1-a146-f94eb1d8e564","evidence-89fe01db-82bb-475e-9d76-5a379bda0e07","evidence-27ebc57b-491d-46f1-bdb3-33df17720f9f","evidence-e925f9c6-bafa-4a0e-bc35-de2a031a6cc9"],"id":"blk-page-main-layout","kind":"page","requirementIds":["blk-prod-scope"],"stage":"product","title":"页面职责与参考图空间结构映射（节点物理替换与无障碍属性保留）"},{"content":"Scenario 1: 正常输入 300ms 防抖自动核对展示
Given 页面已在本地桌面浏览器正常加载且处于待命状态
When 用户在输入框中键入 'AiRDUO-Project-01' 并停止输入超过 300 毫秒
Then 页面顶部展示区自动显示 'AiRDUO-Project-01'，字体醒目大字高对比，输入框保留 'AiRDUO-Project-01'，页面无错误提示，全程无需点击任何确认按钮。

Scenario 2: 中文输入法（IME）拼音合成态防误触
Given 用户聚焦输入框并使用中文拼音输入法键入拼音 'xiangmu'
When 用户在候选字列表选词暂停（处于 compositionstart 与 compositionend 之间，闭包内 isComposing 为 true）
Then 顶部展示区不展示未完成的拼音字母 'xiangmu'，防抖计时挂起；当用户选择候选词确认上屏 '项目' 并停止输入满 300 毫秒后，顶部展示区一次性更新呈现 '项目'。

Scenario 3: 清空后旧节点迟到 compositionend 与尾随 input 不得重显或造错
Given 用户在旧输入框 node_1（bornGeneration=1）中启动拼音输入法合成，尚未完成选词
When 用户直接点击底部橙色圆形清空按钮（触发 node_1.replaceWith(node_2)，inputGeneration 递增为 2），且随后旧输入法引擎向已脱离 DOM 的 node_1 派发迟到的 compositionend 事件与尾随 input 事件
Then node_1 闭包检测到 node_1 !== activeInputNode 且 1 !== 2 立即直接返回，新输入框 node_2 的 value 保持为空字符串 ''，顶部展示区保持占位提示 '【等待输入核对】'；等待 350 毫秒后复查，展示区始终显示 '【等待输入核对】'，页面绝不出现空值错误提示，控制台 0 报错。

Scenario 4: 新节点输入后旧节点 compositionend 不得抹除新草稿或取消新定时器
Given 用户在 node_1 键入拼音后点击清空，系统生成新节点 node_2（bornGeneration=2, inputGeneration=2）
When 用户立即在 node_2 中键入 'Brand-New-2026' 并启动 300ms 防抖，随后 node_1 派发迟到的旧 compositionend 事件
Then node_1 闭包拒绝执行并不操作 activeInputNode，node_2 的 300ms 防抖定时器未被取消，node_2 的 value 完好保持为 'Brand-New-2026'；满 300 毫秒后顶部展示区大字呈现 'Brand-New-2026'。

Scenario 5: 新节点启动新合成后旧节点 compositionend 不得提前结束新合成
Given 用户在 node_1 键入后点击清空生成 node_2，随后用户在 node_2 中启动新的中文输入法拼音输入（node_2 闭包 isComposing 变为 true）
When node_1 派发迟到的旧 compositionend 事件
Then node_1 闭包被守卫拦截直接返回，node_2 闭包中的 isComposing 保持为 true，新拼音草稿不被提前校验，等待新选词上屏后满 300 毫秒正常呈现最终中文项目名。

Scenario 6: 旧定时器已出队后被清空或新输入抢占，旧回调执行无效
Given 用户在输入框中键入 'Temporary-Draft'，300ms 定时器即将到期并已出队进入宏任务队列
When 用户在定时器回调执行前瞬间点击清空按钮（触发 schedulerEpoch 递增并清空），或录入新字符
Then 定时器回调执行时检测到 thisEpoch !== schedulerEpoch（或 targetGeneration !== inputGeneration），立即退出返回，不调用 ValidatorModule，不更新 DOM 展示区，展示区保持为 '【等待输入核对】'。

Scenario 7: 删空文本防抖拦截与旧项目名清除
Given 页面顶部展示区正在展示此前核对成功的项目名 'Old-Alpha-Project'，输入框包含 'Old-Alpha-Project'
When 开发者使用 Backspace/Delete 键将输入框文字全部删空并停止输入满 300 毫秒
Then 顶部展示区原旧项目名 'Old-Alpha-Project' 立即被清除并不再显示，展示区恢复为初始灰色占位文字 '【等待输入核对】'，输入框正下方就地呈现红色警示文字 '项目名不能为空，请输入有效字符'，输入框边框变红，输入框保持空值可编辑焦点，绝不残留旧结果。

Scenario 8: 纯空格输入防抖拦截、旧结果清除与空格保留
Given 页面顶部展示区正在展示 'Old-Alpha-Project'
When 开发者在输入框中输入三个半角空格 '   ' 并停止输入满 300 毫秒
Then 顶部展示区旧项目名立即被清除并恢复为灰色占位文字 '【等待输入核对】'，输入框正下方出现红色明确提示 '项目名不能为空，请输入有效字符'，输入框内输入的三个半角空格完好保留，光标保持在输入框内。

Scenario 9: 运行时异常保留输入
Given 用户在输入框中输入了测试项目名
When 异步回调触发未知运行时错误
Then 页面顶部显示友好错误横幅，输入框内的所有字符完好保留，页面不重载，允许用户修改或重试。","dependsOn":["blk-flow-input-display"],"evidenceIds":["evidence-1e3fc8ef-8a1e-404f-a931-72f46fd0d8ed","evidence-6f045d0d-928d-4f66-8427-b7f62c91ae8a","evidence-15da1e6d-9c13-49f1-a146-f94eb1d8e564","evidence-27ebc57b-491d-46f1-bdb3-33df17720f9f","evidence-dab40954-74e0-4d24-bb31-1064f5dd626f","evidence-7cca7dfc-39e6-47cf-8cc6-3f7ccb9f622e","evidence-dea1091c-52e5-4841-bdfe-a040b152fc88","evidence-e925f9c6-bafa-4a0e-bc35-de2a031a6cc9"],"id":"blk-acc-input-display","kind":"acceptance","requirementIds":["blk-feat-input-display"],"stage":"product","title":"验收标准：300ms 防抖实时反馈、节点替换隔离与精确测试用例 Given-When-Then"},{"content":"Scenario 1: 正常即时清空复位、节点替换与回焦
Given 顶部展示区正在展示 'Project-Test'，输入框包含 'Project-Test'，界面无错误
When 用户点击底部橙色清空按钮
Then 页面不弹出任何二次确认框，旧输入框被新 input 节点物理替换（DOM replaceWith），新节点 value 为空字符串 ''，新节点的 id 依然为 'project-name-input'，name 依然为 'projectName'，aria-label 依然为 '项目名输入'，顶部展示区立即恢复为灰色占位文本 '【等待输入核对】'，输入焦点自动停留在新输入框内。

Scenario 2: 防抖倒计时中清空彻底取消异步任务
Given 用户刚键入 'New-Test'，当前处于 100 毫秒计时窗口
When 用户点击清空按钮
Then 调度纪元 schedulerEpoch 递增，输入框被替换复位，定时器被销毁，等待 500 毫秒后查验展示区依然保持 '【等待输入核对】'，无任何旧文字回显。

Scenario 3: 清除历史错误提示
Given 页面因前次操作正在显示 '项目名不能为空，请输入有效字符' 红色警告
When 用户点击清空按钮
Then 红色警告提示立刻从 DOM 移除，输入框错误高亮取消，页面恢复至干净初始态。

Scenario 4: 空页面重复点击清空幂等性与节点持续可用
Given 页面处于初始空白状态
When 用户连续多次点击清空按钮
Then 页面无任何异常抛出，节点依次正常替换，展示区保持占位提示，当前活跃输入框持续保持聚焦状态，不产生任何空值错误。

Scenario 5: 清空替换后布局无跳动与无障碍关联保留
Given 输入框周围存在对应的 label 标签或外层布局样式
When 点击清空按钮完成节点替换
Then 新节点的 DOM 几何尺寸、类名样式与原有无障碍属性完全一致，界面布局不发生闪烁跳动，屏幕阅读器可正常关联读取。","dependsOn":["blk-flow-reset"],"evidenceIds":["evidence-1e3fc8ef-8a1e-404f-a931-72f46fd0d8ed","evidence-6f045d0d-928d-4f66-8427-b7f62c91ae8a","evidence-15da1e6d-9c13-49f1-a146-f94eb1d8e564","evidence-27ebc57b-491d-46f1-bdb3-33df17720f9f","evidence-89fe01db-82bb-475e-9d76-5a379bda0e07"],"id":"blk-acc-reset","kind":"acceptance","requirementIds":["blk-feat-reset"],"stage":"product","title":"验收标准：清空重置、节点替换与属性保留 Given-When-Then"},{"content":"前端采用低耦合、高内聚的模块化架构，划分为核心应用协调器与 6 个专用功能模块，建立节点物理替换、闭包代际隔离与草稿快照调度体系：
1. AppController（核心应用协调器）：入口装配中心，监听 DOMContentLoaded 事件，初始化获取 DOM 引用，完成首个输入节点的代际闭包绑定（generation = 1），挂载全局 window.addEventListener('error') 兜底，协调组件间流转；
2. InputController（输入节点生命周期与事件闭包监听控制器）：
   - 管理当前活跃输入框节点 activeInputNode 与单调递增的代际计数 inputGeneration；
   - 提供 bindInputNode(node, bornGeneration) 方法：为指定 input 节点闭包绑定 input、beforeinput、compositionstart、compositionend、keydown、paste 事件，并在闭包内维护该节点专有的 isComposing 与 trustedDraft；
   - 事件处理前置严密核验四重守卫：event.currentTarget === node && node === activeInputNode && bornGeneration === inputGeneration && document.body.contains(node)；
   - 提供 replaceInputNode() 方法：递增 inputGeneration，创建属性完备的新 input 节点，绑定新闭包并调用 oldNode.replaceWith(newNode)，更新 activeInputNode 并执行 focus()；
   - 提供 getActiveInputNode()、getInputText()、setInputText(val)、focusInput() 接口；
3. DebounceScheduler（快照防抖调度器）：
   - 维护单调递增的调度纪元 schedulerEpoch 与活跃定时器句柄 pendingTimerId；
   - schedule(draftSnapshot, targetNode, targetGeneration, callback, delayMs = 300)：先调用 cancel() 递增 schedulerEpoch 使旧任务失效，记录当前 thisEpoch = schedulerEpoch，启动 setTimeout；到期执行时校验 thisEpoch === schedulerEpoch && targetGeneration === inputGeneration && targetNode === activeInputNode && document.body.contains(targetNode)，通过后执行 callback(draftSnapshot)；
   - cancel()：若存在 pendingTimerId 则 clearTimeout 并置 null，单调递增 schedulerEpoch 使已排队的宏任务回调失效；
   - isPending()、getEpoch() 状态查询接口；
4. ValidatorModule（规则校验器）：无状态纯函数校验模块，接收 draft 字符串，执行 trim() 校验，返回 { isValid: boolean, errorMessage: string | null }；
5. DisplayRenderer（安全大字展示渲染器）：负责顶部展示区视图更新，强制使用 Node.textContent 纯文本赋值，提供 renderProjectName(text) 与 renderPlaceholder() 接口，空值或清空时将展示区复位为占位符；
6. ResetController（清空复位控制器）：响应清空按钮点击，第一优先级调用 DebounceScheduler.cancel() 废弃待展示任务，调用 InputController.replaceInputNode() 替换输入节点并进入新代际，复位展示区为占位符、移除错误提示并回焦新节点；
7. FeedbackBanner（错误提示组件）：管理输入框下方就地红色错误提示节点（aria-live="polite"）与全局异常横幅。","dependsOn":["blk-tech-stack","blk-feat-input-display","blk-feat-reset"],"evidenceIds":["evidence-1e3fc8ef-8a1e-404f-a931-72f46fd0d8ed","evidence-6f045d0d-928d-4f66-8427-b7f62c91ae8a","evidence-15da1e6d-9c13-49f1-a146-f94eb1d8e564","evidence-27ebc57b-491d-46f1-bdb3-33df17720f9f","evidence-mdn-document-queryselector","evidence-mdn-htmlinputelement","evidence-mdn-node-textcontent-official","evidence-7cca7dfc-39e6-47cf-8cc6-3f7ccb9f622e","evidence-dea1091c-52e5-4841-bdfe-a040b152fc88","evidence-e925f9c6-bafa-4a0e-bc35-de2a031a6cc9"],"id":"blk-tech-module","kind":"module","requirementIds":["blk-prod-scope","blk-feat-input-display","blk-feat-reset"],"stage":"technical","title":"前端系统架构与核心功能模块划分（输入节点闭包绑定与快照调度器）"},{"content":"客户端运行时采用单向流动的纯内存数据模型，不使用任何本地持久化存储（如 LocalStorage、IndexedDB），确保单次测试独立且不污染后续测试：
1. 校验判定结构体（ValidationResult）：
   - isValid: boolean（是否通过非空规则校验）；
   - errorMessage: string | null（未通过时提示文案，例如 '项目名不能为空，请输入有效字符'；通过为 null）。
2. 全局运行时状态模型（AppState）：
   - activeInputNode: HTMLInputElement | null（当前活跃在 DOM 树中的输入框元素引用，初始为页面加载时的 input 节点）；
   - inputGeneration: number（单调递增的输入节点代际计数器，初始为 1；每次清空替换节点时自增 1）；
   - schedulerEpoch: number（单调递增的防抖调度纪元计数器，初始为 0；每次 schedule 替代、cancel、clear 时自增 1）；
   - pendingTimerId: number | null（当前活跃的 300ms 防抖定时器句柄，无排队任务时为 null）；
   - projectName: string | null（当前已核对并在顶部大字展示的项目名，初始态为 null）；
   - validationError: string | null（当前挂载在输入框下方的错误信息，无错误时为 null）；
   - placeholderText: string（顶部展示区在初始、清空或空值态下的灰字占位符，常量定义为 '【等待输入核对】'）。
3. 节点闭包私有上下文模型（NodeClosureContext）：
   - node: HTMLInputElement（当前闭包绑定的输入框节点引用）；
   - bornGeneration: number（当前节点诞生时的代际编号，不可变常量）；
   - isComposing: boolean（当前节点私有的中文输入法合成状态标记，初始为 false）；
   - trustedDraft: string（当前节点已接受的受信任草稿文本，初始为空字符串 ''）。
4. 状态转换路径：
   - [初始态 就绪]：inputGeneration=1, schedulerEpoch=0, pendingTimerId=null, projectName=null, validationError=null -> 展示区呈现灰字占位符，activeInputNode 聚焦等待；
   - [普通输入录入]：核验 e.currentTarget === node && node === activeInputNode && bornGeneration === inputGeneration，更新 trustedDraft=node.value，调用 schedule(trustedDraft, node, bornGeneration, ...)，schedulerEpoch++，pendingTimerId 激活 300ms 倒计时；
   - [IME 合成中]：触发 compositionstart，核验通过后置闭包私有 isComposing=true，调用 cancel()（schedulerEpoch++，pendingTimerId=null）挂起防抖定时器；
   - [IME 选词上屏]：触发 compositionend，核验通过后置闭包私有 isComposing=false，更新 trustedDraft=node.value，调用 schedule(trustedDraft, node, bornGeneration, ...) 重新启动 300ms 倒计时；
   - [清空重置触发]：用户点击清空 -> 立即调用 clearTimeout(pendingTimerId), pendingTimerId=null, schedulerEpoch++, inputGeneration++, 创建新节点 newNode（bornGeneration=inputGeneration, isComposing=false, trustedDraft=''）, oldNode.replaceWith(newNode), activeInputNode=newNode, projectName=null, validationError=null -> 展示区恢复灰字占位符，光标自动回焦 newNode；
   - [旧节点迟到事件到达]：派发至 oldNode，其闭包核查 bornGeneration !== inputGeneration 或 node !== activeInputNode，立即 return 丢弃，完全无法接触 activeInputNode，不制造空值错误；
   - [300ms 到期且非空]：定时器唤醒核查 thisEpoch === schedulerEpoch && targetGeneration === inputGeneration，ValidatorModule 对草稿快照 draftSnapshot 校验通过 -> projectName=draftSnapshot, validationError=null, pendingTimerId=null -> 展示区呈现黑色大字，输入框内容完好保留；
   - [300ms 到期且空值]：对草稿快照 draftSnapshot 校验未通过 -> validationError='项目名不能为空，请输入有效字符', projectName=null, pendingTimerId=null -> 展示区恢复灰字占位符（彻底清除旧项目名结果），输入框原样保留既有输入（含空格）。","dependsOn":["blk-tech-module"],"evidenceIds":["evidence-1e3fc8ef-8a1e-404f-a931-72f46fd0d8ed","evidence-6f045d0d-928d-4f66-8427-b7f62c91ae8a","evidence-15da1e6d-9c13-49f1-a146-f94eb1d8e564","evidence-27ebc57b-491d-46f1-bdb3-33df17720f9f","evidence-7cca7dfc-39e6-47cf-8cc6-3f7ccb9f622e","evidence-e925f9c6-bafa-4a0e-bc35-de2a031a6cc9"],"id":"blk-tech-data-model","kind":"data_model","requirementIds":["blk-prod-scope","blk-feat-input-display","blk-feat-reset"],"stage":"technical","title":"客户端运行时数据模型与状态结构规范（节点代际、调度纪元与草稿快照）"},{"content":"各模块间通过明确的函数签名与原生事件契约进行交互解耦，提供内部自洽、可直接指导编码实现的完整接口契约与伪代码实现：

```javascript
// 全局状态管理
let activeInputNode = null;
let inputGeneration = 1;

// 1. DebounceScheduler 模块接口契约
const DebounceScheduler = (() => {
  let pendingTimerId = null;
  let schedulerEpoch = 0;

  function schedule(draftSnapshot, targetNode, targetGeneration, callback, delayMs = 300) {
    cancel(); // 清除排队任务并递增 schedulerEpoch 使旧回调失效
    const thisEpoch = ++schedulerEpoch;
    pendingTimerId = window.setTimeout(() => {
      // 唤醒守卫：即便回调已出队进入宏任务，若纪元、代际或节点不匹配，立即作废返回
      if (thisEpoch !== schedulerEpoch) return;
      if (targetGeneration !== inputGeneration) return;
      if (targetNode !== activeInputNode) return;
      if (!document.body.contains(targetNode)) return;

      pendingTimerId = null;
      // 严格使用捕获的草稿快照进行校验与输出，绝不重读可能已被篡改的 DOM value
      callback(draftSnapshot);
    }, delayMs);
  }

  function cancel() {
    if (pendingTimerId !== null) {
      window.clearTimeout(pendingTimerId);
      pendingTimerId = null;
    }
    schedulerEpoch++; // 递增纪元使任何待执行或已出队的旧定时器失效
  }

  function isPending() {
    return pendingTimerId !== null;
  }

  function getEpoch() {
    return schedulerEpoch;
  }

  return { schedule, cancel, isPending, getEpoch };
})();

// 2. InputController 模块接口契约
const InputController = (() => {
  function isNodeActiveAndCurrent(e, node, bornGeneration) {
    return e.currentTarget === node &&
           node === activeInputNode &&
           bornGeneration === inputGeneration &&
           document.body.contains(node);
  }

  function bindInputNode(node, bornGeneration) {
    // 节点闭包私有变量
    let isComposing = false;
    let trustedDraft = '';

    node.addEventListener('compositionstart', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
      isComposing = true;
      DebounceScheduler.cancel(); // 挂起防抖并使旧纪元失效
    });

    node.addEventListener('compositionend', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
      isComposing = false;
      trustedDraft = node.value;
      DebounceScheduler.schedule(trustedDraft, node, bornGeneration, handleDebouncedValidateAndDisplay, 300);
    });

    node.addEventListener('input', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
      if (!isComposing && !e.isComposing) {
        trustedDraft = node.value;
        DebounceScheduler.schedule(trustedDraft, node, bornGeneration, handleDebouncedValidateAndDisplay, 300);
      }
    });

    node.addEventListener('beforeinput', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
    });

    node.addEventListener('keydown', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
    });

    node.addEventListener('paste', (e) => {
      if (!isNodeActiveAndCurrent(e, node, bornGeneration)) return;
    });
  }

  function replaceInputNode() {
    const oldNode = activeInputNode;
    inputGeneration++;
    const nextGen = inputGeneration;

    const newNode = document.createElement('input');
    newNode.type = 'text';
    newNode.id = oldNode.id;
    newNode.name = oldNode.name;
    newNode.className = oldNode.className;
    newNode.placeholder = oldNode.placeholder;
    newNode.setAttribute('aria-label', oldNode.getAttribute('aria-label') || '项目名输入');
    newNode.value = '';

    bindInputNode(newNode, nextGen);

    if (oldNode && oldNode.parentNode) {
      oldNode.replaceWith(newNode);
    }
    activeInputNode = newNode;
    return activeInputNode;
  }

  function init(initialNode) {
    activeInputNode = initialNode;
    bindInputNode(activeInputNode, inputGeneration);
  }

  function getActiveInputNode() {
    return activeInputNode;
  }

  function focusInput() {
    if (activeInputNode) activeInputNode.focus();
  }

  return { init, bindInputNode, replaceInputNode, getActiveInputNode, focusInput };
})();

// 3. ValidatorModule 接口契约
const ValidatorModule = (() => {
  function validate(rawInput) {
    if (typeof rawInput !== 'string') {
      return { isValid: false, errorMessage: '项目名不能为空，请输入有效字符' };
    }
    const trimmed = rawInput.trim();
    if (trimmed.length === 0) {
      return { isValid: false, errorMessage: '项目名不能为空，请输入有效字符' };
    }
    return { isValid: true, errorMessage: null };
  }
  return { validate };
})();

// 4. handleDebouncedValidateAndDisplay 执行契约
function handleDebouncedValidateAndDisplay(draftSnapshot) {
  try {
    const validation = ValidatorModule.validate(draftSnapshot);
    if (!validation.isValid) {
      // 空值或纯空格：彻底清除旧项目名展示并恢复占位符，挂载错误提示，输入框草稿完好保留
      DisplayRenderer.renderPlaceholder(displayElement, '【等待输入核对】');
      FeedbackBanner.showInputError(InputController.getActiveInputNode(), errorContainer, validation.errorMessage);
    } else {
      // 有效非空字符：移除错误提示，通过 textContent 安全输出草稿快照
      FeedbackBanner.clearInputError(InputController.getActiveInputNode(), errorContainer);
      DisplayRenderer.renderProjectName(displayElement, draftSnapshot);
    }
  } catch (err) {
    FeedbackBanner.showGlobalError('处理输入时遇到异常，已为您保留当前输入');
    console.error('防抖回调异常:', err);
  }
}

// 5. DisplayRenderer 接口契约
const DisplayRenderer = (() => {
  function renderProjectName(targetElement, text) {
    targetElement.textContent = text;
    targetElement.classList.remove('placeholder');
    targetElement.classList.add('active-result');
  }
  function renderPlaceholder(targetElement, placeholder = '【等待输入核对】') {
    targetElement.textContent = placeholder;
    targetElement.classList.remove('active-result');
    targetElement.classList.add('placeholder');
  }
  return { renderProjectName, renderPlaceholder };
})();

// 6. ResetController 接口契约
const ResetController = (() => {
  function handleReset() {
    try {
      // 1. 立即取消待展示防抖任务并废弃调度纪元
      DebounceScheduler.cancel();
      // 2. 递增代际，创建新输入节点物理替换旧节点，绑定新闭包
      const newInputNode = InputController.replaceInputNode();
      // 3. 顶部展示区恢复为占位符
      DisplayRenderer.renderPlaceholder(displayElement, '【等待输入核对】');
      // 4. 清除错误提示
      FeedbackBanner.clearInputError(newInputNode, errorContainer);
      // 5. 焦点自动回焦到新输入节点
      InputController.focusInput();
    } catch (err) {
      FeedbackBanner.showGlobalError('重置时遇到异常，界面保持可编辑');
      console.error('清空重置异常:', err);
    }
  }
  return { handleReset };
})();
```

7. 后台延迟与前台测量契约：
   - 防抖调度延迟性能测量严格以前台可见状态（document.visibilityState === 'visible'）为基准；后台标签页可能受浏览器底层节流延迟唤醒，唤醒时由于调度纪元 thisEpoch 与代际 targetGeneration 核验，任何已被清空或后发输入覆盖的任务均立即安全返回，杜绝竞态。","dependsOn":["blk-tech-data-model"],"evidenceIds":["evidence-1e3fc8ef-8a1e-404f-a931-72f46fd0d8ed","evidence-6f045d0d-928d-4f66-8427-b7f62c91ae8a","evidence-15da1e6d-9c13-49f1-a146-f94eb1d8e564","evidence-mdn-htmlinputelement","evidence-mdn-node-textcontent-official","evidence-7cca7dfc-39e6-47cf-8cc6-3f7ccb9f622e","evidence-dea1091c-52e5-4841-bdfe-a040b152fc88","evidence-mdn-ime-compositionstart-session","evidence-e925f9c6-bafa-4a0e-bc35-de2a031a6cc9","evidence-8978eaa8-d822-4c9c-a5c5-c60e914c2a91","evidence-f7c8f543-aa2f-4d11-bcf6-eb506e933aba"],"id":"blk-tech-interface","kind":"interface","requirementIds":["blk-feat-input-display","blk-feat-reset"],"stage":"technical","title":"组件事件契约与模块调用接口规范（节点代际守卫、调度纪元与完整伪代码）"},{"content":"建立全面的客户端异常捕获与容错恢复机制，重点落实“失败时保留输入”决策、旧结果清除与节点物理替换闭包代际隔离策略：
1. E01 防抖校验拦截（空值或纯空白字符输入）：
